#include <libxml/parser.h>
#include <OpenMS/FORMAT/HANDLERS/MzMLSpectrumDecoder.h>
#include <iostream>
int main(){std::string dtd="<!DOCTYPE spectrum [<!ENTITY e0 '"+std::string(100000,'A')+"'>";for(int i=1;i<=2;++i){dtd+="<!ENTITY e"+std::to_string(i)+" '";for(int j=0;j<10;++j)dtd+="&e"+std::to_string(i-1)+";";dtd+="'>";}const auto input=dtd+"]><spectrum defaultArrayLength='0'>&e2;</spectrum>";auto*p=xmlNewParserCtxt();xmlCtxtSetMaxAmplification(p,5);std::cout<<"before HUGE maxAmpl="<<p->maxAmpl<<"\n";xmlCtxtUseOptions(p,XML_PARSE_HUGE|XML_PARSE_NOENT|XML_PARSE_NONET|XML_PARSE_NO_XXE);std::cout<<"after HUGE maxAmpl="<<p->maxAmpl<<"\n";auto*d=xmlCtxtReadMemory(p,input.data(),input.size(),"bounded.xml",nullptr,XML_PARSE_HUGE|XML_PARSE_NOENT|XML_PARSE_NONET|XML_PARSE_NO_XXE);const auto*err=xmlCtxtGetLastError(p);std::cout<<"direct returned_doc="<<(d!=nullptr)<<" error="<<(err?err->code:0)<<" message="<<(err&&err->message?err->message:"")<<"\n";bool guarded=!d&&err&&err->code==XML_ERR_RESOURCE_LIMIT;xmlFreeDoc(d);xmlFreeParserCtxt(p);OpenMS::MzMLSpectrumDecoder decoder;OpenMS::MSSpectrum spectrum;try{decoder.domParseSpectrum(input,spectrum);std::cout<<"OpenMS accepted\n";return 1;}catch(const OpenMS::Exception::ParseError&){std::cout<<"OpenMS rejected with ParseError\n";}return guarded?0:1;}
